// Este script recibe el paquete completo del webhook y hace todo el trabajo.

const webhookData = items[0].json;

// Soporta body directo o body stringificado
let body = webhookData.body;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (e) {
    throw new Error("El 'body' vino como string pero no se pudo parsear JSON.");
  }
}

const transfers = body?.transfers ?? [];

if (!Array.isArray(transfers)) {
  throw new Error("Error: Se esperaba una lista en 'body.transfers', pero se recibió otra cosa.");
}

if (transfers.length === 0) {
  return [];
}

// Helpers
const padMillis = (num) => num.toString().padStart(4, '0'); // ssss

function toCleanNumber(value) {
  // Convierte strings tipo "1\n", "$ 1.234,56", "1234" a Number
  if (value === null || value === undefined) return null;

  const s = String(value)
    .trim()
    .replace(/\s+/g, '')          // quita espacios/saltos de línea
    .replace(/[^\d,.\-]/g, '');   // quita símbolos ( $, etc )

  if (!s) return null;

  // Normaliza separadores:
  // si tiene "." y "," asumimos miles "." y decimal ","
  let normalized = s;
  if (s.includes(',') && s.includes('.')) normalized = s.replace(/\./g, '').replace(',', '.');
  else if (s.includes(',')) normalized = s.replace(',', '.');

  const n = Number.parseFloat(normalized);
  return Number.isFinite(n) ? n : null;
}

// Limpia textos tipo "Ingreso (Test)" -> "Ingreso"
function cleanLabel(v) {
  return String(v ?? '')
    .trim()
    .replace(/\s*\([^)]*\)\s*$/, '') // elimina "(...)” al final
    .trim();
}

// Decide el tipo EXACTO que espera tu Select de Notion
function resolveNotionTipo(transfer) {
  const directionUpper = String(transfer.direction ?? '').trim().toUpperCase();
  const sourceClean = cleanLabel(transfer.source).toLowerCase();
  const nameClean = cleanLabel(transfer.name).toLowerCase();

  // 1) Si viene indicado como rendimiento por "source" o "name", priorizamos Rendimientos
  if (sourceClean.includes('rendimiento') || nameClean.includes('rendimiento')) {
    return 'Rendimientos';
  }

  // 2) Si es ingreso: Transferencia recibida
  if (directionUpper === 'INGRESO' || directionUpper === 'IN' || directionUpper === 'CREDIT') {
    return 'Transferencia recibida';
  }

  // 3) Si es egreso: Transferencia enviada
  if (directionUpper === 'EGRESO' || directionUpper === 'OUT' || directionUpper === 'DEBIT') {
    return 'Transferencia enviada';
  }

  // 4) Fallback seguro
  return 'Transferencia recibida';
}

// Normaliza direction para no confundir IN/CREDIT con EGRESO
function classifyDirection(directionRaw) {
  const d = String(directionRaw ?? '').trim().toUpperCase();
  const isIngreso = (d === 'INGRESO' || d === 'IN' || d === 'CREDIT');
  const isEgreso  = (d === 'EGRESO'  || d === 'OUT' || d === 'DEBIT');
  return { d, isIngreso, isEgreso };
}

const outputItems = transfers.map((transfer) => {

  // 1) Timestamp -> Date
  const timestampNumber = Number(String(transfer.timestampMs ?? '').trim());
  if (!Number.isFinite(timestampNumber) || timestampNumber === 0) {
    throw new Error(`Timestamp inválido para la transferencia ID ${transfer.id}. Valor recibido: '${transfer.timestampMs}'`);
  }

  const dateObject = new Date(timestampNumber);

  // Formato solicitado: aaaa.mm.dd hh:mm.ssss (sin Z)
  // Forzamos timezone Argentina por si el server está en UTC
  const parts = new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'America/Argentina/Buenos_Aires',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  }).formatToParts(dateObject);

  const get = (type) => parts.find(p => p.type === type)?.value;

  const customDateString =
    `${get('year')}.${get('month')}.${get('day')} ` +
    `${get('hour')}:${get('minute')}.` +
    `${padMillis(dateObject.getMilliseconds())}`;

  // 2) Amount cents -> decimal (robusto)
  const amountCents = toCleanNumber(transfer.amountCents);
  if (amountCents === null) {
    throw new Error(`amountCents inválido para la transferencia ID ${transfer.id}. Valor recibido: '${transfer.amountCents}'`);
  }

  const amountAsDecimal = amountCents / 100;

  // 3) Monto para el título
  const formattedAmountForTitle = new Intl.NumberFormat('es-AR', {
    style: 'currency',
    currency: 'ARS'
  }).format(amountAsDecimal);

  // 4) Tipo select EXACTO para Notion (y fallback para inferencia)
  const notion_tipo = resolveNotionTipo(transfer);

  // 5) Clasificar dirección (CORREGIDO)
  const { isIngreso, isEgreso } = classifyDirection(transfer.direction);

  // Si la dirección viene rara/vacía, inferimos por el tipo:
  // - Transferencia recibida -> ingreso
  // - Transferencia enviada  -> egreso
  // - Rendimientos           -> ingreso (podés cambiarlo si querés)
  const inferredIngreso = (notion_tipo === 'Transferencia recibida' || notion_tipo === 'Rendimientos');
  const inferredEgreso  = (notion_tipo === 'Transferencia enviada');

  const finalIsIngreso = isIngreso || (!isEgreso && inferredIngreso);
  const finalIsEgreso  = isEgreso  || (!isIngreso && inferredEgreso);

  // 6) Título (usa la clasificación final)
  let title = '';
  if (finalIsIngreso) {
    title = `Ingreso de ${transfer.name}: ${formattedAmountForTitle}`;
  } else {
    title = `Envío a ${transfer.name}: ${formattedAmountForTitle}`;
  }

  // 7) Montos separados para Notion (CORREGIDO)
  const notion_ingreso = finalIsIngreso ? Number(amountAsDecimal) : 0;
  const notion_egreso  = finalIsEgreso  ? Number(amountAsDecimal) : 0;

  // 8) Sacar direction del output
  const { direction, ...transferWithoutDirection } = transfer;

  return {
    json: {
      ...transferWithoutDirection,
      notion_title: title,
      notion_ingreso,
      notion_egreso,
      notion_tipo,     // <-- ESTE VA A TU SELECT
      notion_date: customDateString
    }
  };
});

return outputItems;

