  const curYear  = dateObj.getFullYear();
  const curMonth = String(dateObj.getMonth() + 1).padStart(2, '0');
  const period = `${curYear}-${curMonth}`;

  if (countersByPeriod[period] == null) countersByPeriod[period] = 0;

  // Secuencia
  countersByPeriod[period] += 1;
  const seq = countersByPeriod[period];

  const newName = `${prefix}-${curYear}-${curMonth}-${String(seq).padStart(4,'0')}`;

  // Amount
  const amountCents = toCleanNumber(t.amountCents);
  if (amountCents === null) {
    throw new Error(`amountCents inválido en transferencia id=${t.id}. Recibido: '${t.amountCents}'`);
  }
  const amount = amountCents / 100;

  // Tipo select
  const notion_tipo = resolveNotionTipo(t);

  // Dirección => ingreso/egreso (corregido)
