  const inferredEgreso  = (notion_tipo === 'Transferencia enviada');

  const finalIsIngreso = isIngreso || (!isEgreso && inferredIngreso);
  const finalIsEgreso  = isEgreso  || (!isIngreso && inferredEgreso);

  const notion_ingreso = finalIsIngreso ? Number(amount) : 0;
  const notion_egreso  = finalIsEgreso  ? Number(amount) : 0;

  // Concepto (rich_text)
  const formattedAmount = new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS' }).format(amount);
  const notion_title = finalIsIngreso
    ? `Ingreso de ${t.name}: ${formattedAmount}`
    : `Envío a ${t.name}: ${formattedAmount}`;

  return {
