      egresos: notion_egreso,      // <-- Egresos (Number)
      timestampMs: ts,             // <-- Fecha (Text) si querés guardar ms

      // extras por si necesitás debug
      _lastRegistrationRaw: lastRegistrationRaw,
      _period: period,
      _seq: seq
    }
  };
});

