        ? Number(String(lastSaldoRaw).replace(",", "."))
        : null);

const re = /^(FIN-[A-Z0-9]+)-(\d{4})-(\d{2})-(\d{4})$/i;
const m = lastName.match(re);

if (!m) {
  throw new Error(`Formato inesperado en name: "${lastName}". Esperado: FIN-XXXX-YYYY-MM-0000`);
}

const prefix = m[1].toUpperCase();
const lastYear = parseInt(m[2], 10);
const lastMonth = m[3];             // "02"
const lastSeq = parseInt(m[4], 10); // 2

// Mes/año actual (según el reloj del servidor donde corre n8n)
const now = new Date();
const nowYear = now.getFullYear();
const nowMonth = String(now.getMonth() + 1).padStart(2, "0");

// Si cambia mes o año => reinicia correlativo
const changedPeriod = (nowYear !== lastYear) || (nowMonth !== lastMonth);
const nextSeq = changedPeriod ? 1 : (lastSeq + 1);

const newName = `${prefix}-${nowYear}-${nowMonth}-${String(nextSeq).padStart(4, "0")}`;

return [
  {
    json: {
      lastName,
      lastSaldo,          // <-- saldo del último registro (salida)
      prefix,
      lastYear,
      lastMonth,
      lastSeq,
      nowYear,
      nowMonth,
      changedPeriod,
      newName
    }
  }
];

// Entrada esperada desde Notion Get Many (último registro):
// $json.name = "FIN-BANCOA-2026-02-0002"
// $json.property_saldo = 1670852.19  (puede venir número o string)

// -------------------- Validación --------------------
const lastName = String($json.name || "").trim();
if (!lastName) throw new Error("No vino $json.name desde Notion (último registro)");

// -------------------- Saldo previo --------------------
const lastSaldoRaw = $json.property_saldo;
const lastSaldo =
  typeof lastSaldoRaw === "number"
    ? lastSaldoRaw
    : (lastSaldoRaw != null && String(lastSaldoRaw).trim() !== ""
        ? Number(String(lastSaldoRaw).replace(",", "."))
        : null);

// -------------------- Parse del name --------------------
const re = /^(FIN-[A-Z0-9]+)-(\d{4})-(\d{2})-(\d{4})$/i;
const m = lastName.match(re);

if (!m) {
  throw new Error(`Formato inesperado en name: "${lastName}". Esperado: FIN-XXXX-YYYY-MM-0000`);
}

const prefix = m[1].toUpperCase();
const lastYear = parseInt(m[2], 10);
const lastMonth = m[3];             // "02"
const lastSeq = parseInt(m[4], 10); // 2

// -------------------- Generar timestampMs y fecha actual --------------------
// timestampMs: número (ms desde epoch)
const now = new Date();
const timestampMs = now.getTime();

// (Opcional) fecha formateada como texto si la querés seguir usando
const padMillis = (num) => String(num).padStart(4, "0");

const parts = new Intl.DateTimeFormat("sv-SE", {
  timeZone: "America/Argentina/Buenos_Aires",
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hour12: false,
}).formatToParts(now);

const get = (type) => parts.find((p) => p.type === type)?.value;

const notion_date =
  `${get("year")}.${get("month")}.${get("day")} ` +
  `${get("hour")}:${get("minute")}.` +
  `${padMillis(now.getMilliseconds())}`;

// Año/mes actual (Argentina) para el correlativo
const nowYear = parseInt(get("year"), 10);
const nowMonth = String(get("month")).padStart(2, "0");

// -------------------- Calcular newName --------------------
const changedPeriod = (nowYear !== lastYear) || (nowMonth !== lastMonth);
const nextSeq = changedPeriod ? 1 : (lastSeq + 1);

const newName = `${prefix}-${nowYear}-${nowMonth}-${String(nextSeq).padStart(4, "0")}`;

// -------------------- Salida adaptada al nodo Notion Create --------------------
return [
  {
    json: {
      // NUEVO: requerido por tu nodo siguiente
      timestampMs,             // número
      name: "Rendimientos",    // texto fijo para Titular/Concepto

      // Para el select
      notion_tipo: "Rendimientos",

      // Montos
      notion_ingreso: 0,
      notion_egreso: 0,

      // Si tu Fecha en Notion es texto, podés usar esto o timestampMs (a elección)
      notion_date,

      // Para el Title/N° de Registro
      newName,

      // Info útil (por si después calculás saldo)
      lastName,
      lastSaldo,
      prefix,
      lastYear,
      lastMonth,
      lastSeq,
      nowYear,
      nowMonth,
      changedPeriod,
    }
  }
];

/**
 * Optimizado:
 * - 1 llamada a Notion para obtener el último registro (limit 1)
 * - Genera IDs para TODAS las transferencias en un solo Code node
 * - Normaliza direction para evitar que IN/CREDIT caiga como egreso
 * - Devuelve campos listos para el nodo "Crear en Notion"
 */

// ------------- Helpers -------------
function safeJsonParse(v) {
  if (typeof v === 'string') {
    try { return JSON.parse(v); } catch (e) { return null; }
  }
  return v ?? null;
}

function toCleanNumber(value) {
  if (value === null || value === undefined) return null;

  const s = String(value)
    .trim()
    .replace(/\s+/g, '')
    .replace(/[^\d,.\-]/g, '');

  if (!s) return null;

  let normalized = s;
  if (s.includes(',') && s.includes('.')) normalized = s.replace(/\./g, '').replace(',', '.');
  else if (s.includes(',')) normalized = s.replace(',', '.');

  const n = Number.parseFloat(normalized);
  return Number.isFinite(n) ? n : null;
}

function cleanLabel(v) {
  return String(v ?? '')
    .trim()
    .replace(/\s*\([^)]*\)\s*$/, '')
    .trim();
}

function classifyDirection(directionRaw) {
  const d = String(directionRaw ?? '').trim().toUpperCase();
  const isIngreso = (d === 'INGRESO' || d === 'IN' || d === 'CREDIT');
  const isEgreso  = (d === 'EGRESO'  || d === 'OUT' || d === 'DEBIT');
  return { d, isIngreso, isEgreso };
}

function resolveNotionTipo(transfer) {
  const directionUpper = String(transfer.direction ?? '').trim().toUpperCase();
  const sourceClean = cleanLabel(transfer.source).toLowerCase();
  const nameClean = cleanLabel(transfer.name).toLowerCase();

  if (sourceClean.includes('rendimiento') || nameClean.includes('rendimiento')) return 'Rendimientos';
  if (directionUpper === 'INGRESO' || directionUpper === 'IN' || directionUpper === 'CREDIT') return 'Transferencia recibida';
  if (directionUpper === 'EGRESO'  || directionUpper === 'OUT' || directionUpper === 'DEBIT')  return 'Transferencia enviada';
  return 'Transferencia recibida';
}

// ------------- Leer último registro desde Notion (entrada del nodo anterior) -------------
const lastRegistrationRaw =
  String($json.name ?? '').trim() ||
  // fallback: si por alguna razón $json.name no viene, intentamos leer desde properties
  String($json?.properties?.['N° de Registro']?.title?.[0]?.plain_text ?? '').trim() ||
  "FIN-BANCOA-2000-01-0000";

const re = /^(FIN-[A-Z0-9]+)-(\d{4})-(\d{2})-(\d{4})$/i;
const m = lastRegistrationRaw.match(re);

const prefix = (m ? m[1] : "FIN-BANCOA").toUpperCase();
const lastYear  = m ? parseInt(m[2], 10) : 2000;
const lastMonth = m ? m[3] : "01";
const lastSeq   = m ? parseInt(m[4], 10) : 0;

// ------------- Leer transfers desde Webhook -------------
const webhookData = $node["Webhook1"].json;
const body = safeJsonParse(webhookData?.body) ?? webhookData?.body ?? webhookData;
const transfers = Array.isArray(body?.transfers) ? body.transfers : [];

if (transfers.length === 0) return [];

// Ordena por timestamp asc para que el correlativo sea estable
transfers.sort((a,b) => (Number(a.timestampMs||0) - Number(b.timestampMs||0)));

// Contadores por periodo YYYY-MM
const countersByPeriod = {};

// Semilla: si el periodo coincide con el último registro, arrancamos desde lastSeq
const lastPeriod = `${lastYear}-${lastMonth}`;
countersByPeriod[lastPeriod] = lastSeq;

return transfers.map((t) => {
  // Timestamp
  const ts = Number(String(t.timestampMs ?? '').trim());
  if (!Number.isFinite(ts) || ts === 0) {
    throw new Error(`timestampMs inválido en transferencia id=${t.id}. Recibido: '${t.timestampMs}'`);
  }

  const dateObj = new Date(ts);
  const curYear  = dateObj.getFullYear();
  const curMonth = String(dateObj.getMonth() + 1).padStart(2, '0');
  const period = `${curYear}-${curMonth}`;

  if (countersByPeriod[period] == null) countersByPeriod[period] = 0;

  // Secuencia
  countersByPeriod[period] += 1;
  const seq = countersByPeriod[period];

  const newName = `${prefix}-${curYear}-${curMonth}-${String(seq).padStart(4,'0')}`;

  // Amount
  const amountCents = toCleanNumber(t.amountCents);
  if (amountCents === null) {
    throw new Error(`amountCents inválido en transferencia id=${t.id}. Recibido: '${t.amountCents}'`);
  }
  const amount = amountCents / 100;

  // Tipo select
  const notion_tipo = resolveNotionTipo(t);

  // Dirección => ingreso/egreso (corregido)
  const { isIngreso, isEgreso } = classifyDirection(t.direction);

  // fallback por tipo si direction viene raro
  const inferredIngreso = (notion_tipo === 'Transferencia recibida' || notion_tipo === 'Rendimientos');
  const inferredEgreso  = (notion_tipo === 'Transferencia enviada');

  const finalIsIngreso = isIngreso || (!isEgreso && inferredIngreso);
  const finalIsEgreso  = isEgreso  || (!isIngreso && inferredEgreso);

  const notion_ingreso = finalIsIngreso ? Number(amount) : 0;
  const notion_egreso  = finalIsEgreso  ? Number(amount) : 0;

  // Concepto (rich_text)
  const formattedAmount = new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS' }).format(amount);
  const notion_title = finalIsIngreso
    ? `Ingreso de ${t.name}: ${formattedAmount}`
    : `Envío a ${t.name}: ${formattedAmount}`;

  return {
    json: {
      // para el Create
      newName,
      name: notion_title,          // <-- Titular/Concepto
      tipo: notion_tipo,           // <-- Tipo|select (Option Name)
      ingresos: notion_ingreso,    // <-- Ingresos (Number)
      egresos: notion_egreso,      // <-- Egresos (Number)
      timestampMs: ts,             // <-- Fecha (Text) si querés guardar ms

      // extras por si necesitás debug
      _lastRegistrationRaw: lastRegistrationRaw,
      _period: period,
      _seq: seq
    }
  };
});
